      currency: "XOF",
      country_code: "SN",
      operator: "orange",
      phone: "+221770000000",
      order_id: "PAYOUT-20240501-042",
      webhook_url: "https://yourapp.com/webhook/drimpay",
      description: "Supplier payment May 2026",
